// Command enrich-scoop-manifest adds Scoop's release discovery metadata to the
// manifest generated by GoReleaser.
package main

import (
	"encoding/json"
	"fmt"
	"os"
)

func main() {
	if len(os.Args) != 2 {
		fatalf("usage: enrich-scoop-manifest <manifest.json>")
	}

	path := os.Args[1]
	data, err := os.ReadFile(path)
	if err != nil {
		fatalf("read manifest: %v", err)
	}

	var manifest map[string]any
	if err := json.Unmarshal(data, &manifest); err != nil {
		fatalf("decode manifest: %v", err)
	}

	manifest["checkver"] = "github"
	manifest["autoupdate"] = map[string]any{
		"architecture": map[string]any{
			"32bit": map[string]string{
				"url": "https://github.com/wanetty/upgopher/releases/download/v$version/upgopher_$version_windows_386.zip",
			},
			"64bit": map[string]string{
				"url": "https://github.com/wanetty/upgopher/releases/download/v$version/upgopher_$version_windows_amd64.zip",
			},
			"arm64": map[string]string{
				"url": "https://github.com/wanetty/upgopher/releases/download/v$version/upgopher_$version_windows_arm64.zip",
			},
		},
		"hash": map[string]string{
			"url": "$baseurl/checksums.txt",
		},
	}

	output, err := json.MarshalIndent(manifest, "", "    ")
	if err != nil {
		fatalf("encode manifest: %v", err)
	}
	output = append(output, '\n')
	if err := os.WriteFile(path, output, 0o644); err != nil {
		fatalf("write manifest: %v", err)
	}
}

func fatalf(format string, args ...any) {
	_, _ = fmt.Fprintf(os.Stderr, format+"\n", args...)
	os.Exit(1)
}
